        public void Print(
            IRagdollGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Ragdoll.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Ragdoll =>");
            }
            else
            {
                sb.AppendLine($"{name} (Ragdoll) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
        protected static void ToStringFields(
            IRagdollGetter item,
            StructuredStringBuilder sb,
            Ragdoll.Mask<bool>? printMask = null)
        {
            Fallout3MajorRecordCommon.ToStringFields(
                item: item,
                sb: sb,
                printMask: printMask);
            if (printMask?.Version ?? true)
            {
                sb.AppendItem(item.Version, "Version");
            }
            if (printMask?.DynamicBoneCount ?? true)
            {
                sb.AppendItem(item.DynamicBoneCount, "DynamicBoneCount");
            }
            if (printMask?.Unused ?? true)
            {
                sb.AppendItem(item.Unused, "Unused");
            }
            if (printMask?.FeedbackEnabled ?? true)
            {
                sb.AppendItem(item.FeedbackEnabled, "FeedbackEnabled");
            }
            if (printMask?.FootIkEnabled ?? true)
            {
                sb.AppendItem(item.FootIkEnabled, "FootIkEnabled");
            }
            if (printMask?.LookIkEnabled ?? true)
            {
                sb.AppendItem(item.LookIkEnabled, "LookIkEnabled");
            }
            if (printMask?.GrabIkEnabled ?? true)
            {
                sb.AppendItem(item.GrabIkEnabled, "GrabIkEnabled");
            }
            if (printMask?.PoseMatchingEnabled ?? true)
            {
                sb.AppendItem(item.PoseMatchingEnabled, "PoseMatchingEnabled");
            }
            if (printMask?.Unused2 ?? true)
            {
                sb.AppendItem(item.Unused2, "Unused2");
            }
            if (printMask?.ActorBase ?? true)
            {
                sb.AppendItem(item.ActorBase.FormKeyNullable, "ActorBase");
            }
            if (printMask?.BodyPartData ?? true)
            {
                sb.AppendItem(item.BodyPartData.FormKey, "BodyPartData");
            }
            if (printMask?.FeedbackData?.Overall ?? true)
            {
                item.FeedbackData?.Print(sb, "FeedbackData");
            }
            if ((printMask?.FeedbackDynamicBones?.Overall ?? true)
                && item.FeedbackDynamicBones is {} FeedbackDynamicBonesItem)
            {
                sb.AppendLine("FeedbackDynamicBones =>");
                using (sb.Brace())
                {
                    foreach (var subItem in FeedbackDynamicBonesItem)
                    {
                        using (sb.Brace())
                        {
                            sb.AppendItem(subItem, "Bone");
                        }
                    }
                }
            }
            if (printMask?.PoseMatchingData?.Overall ?? true)
            {
                item.PoseMatchingData?.Print(sb, "PoseMatchingData");
            }
            if ((printMask?.DeathPose ?? true)
                && item.DeathPose is {} DeathPoseItem)
            {
                sb.AppendItem(DeathPoseItem, "DeathPose");
            }
        }
        
